package karrar;

public class star4 {

	public static void main(String[] args) {
		char k='A';
	
		// TODO Auto-generated method stub
				for (int j=1;j<=4;j++)
				{
					for(int i=1;i<=j;i++)
					{
						
						
						System.out.print(k+" ");
						k++;
						
					}
					System.out.println();
				}
	}
}

		


		
		
